package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	// Read and discard first token
	fmt.Fscan(in, new(string))
	// Read second token
	var str string
	fmt.Fscan(in, &str)

	if strings.Contains(str, "CC") || strings.Contains(str, "YY") || strings.Contains(str, "MM") {
		fmt.Println("No")
		return
	}

	if strings.HasPrefix(str, "?") ||
		strings.HasSuffix(str, "?") ||
		strings.Contains(str, "??") ||
		strings.Contains(str, "C?C") ||
		strings.Contains(str, "Y?Y") ||
		strings.Contains(str, "M?M") {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}

